INSERT OVERWRITE lr_serverless_aws_us_catalog.meridian_reference.run_verdict VALUES
  ('GREEN', 'Green', 'All quality checks passed; results released downstream.'),
  ('AMBER', 'Amber', 'Passed with warnings; released with commentary.'),
  ('RED', 'Red', 'Quality gate failed; results blocked from downstream use.');

INSERT OVERWRITE lr_serverless_aws_us_catalog.meridian_reference.scenario_status VALUES
  ('ACTIVE', 'Active', 'The scenario set used by production valuation runs.'),
  ('AVAILABLE', 'Available', 'Delivered and validated, usable for analysis, not the production set.'),
  ('SUPERSEDED', 'Superseded', 'Replaced by a newer set; retained for reproducibility.');

INSERT OVERWRITE lr_serverless_aws_us_catalog.meridian_reference.source_system VALUES
  ('PAS_CORE', 'Policy Administration (Core)', 'The group''s core policy administration system.'),
  ('CLM_CORE', 'Claims (Core)', 'The group''s core claims management system.'),
  ('RI_CORE', 'Reinsurance (Core)', 'The group''s reinsurance administration system.'),
  ('DATA_CORE', 'Data Core (Mastered)', 'Records mastered or derived inside the data layer itself, such as deduplicated golden party records.'),
  ('LIFE_CORE', 'Life Administration (Core)', 'The group''s life policy administration and valuation feed.'),
  ('COVERHOLDER_BDX', 'Coverholder Bordereau', 'Lines reported by coverholders or brokers via bordereaux and mapped into the canonical model through the exchange domain.');

INSERT OVERWRITE lr_serverless_aws_us_catalog.meridian_reference.submission_status VALUES
  ('RECEIVED', 'Received', 'Submission received and awaiting triage.'),
  ('IN_REVIEW', 'In Review', 'Under triage, pricing and accumulation assessment.'),
  ('QUOTED', 'Quoted', 'Terms quoted back to the cedant or broker.'),
  ('BOUND', 'Bound', 'Accepted and bound; a treaty exists for this submission.'),
  ('DECLINED', 'Declined', 'Declined by the reinsurer.'),
  ('WITHDRAWN', 'Withdrawn', 'Withdrawn by the cedant or broker before a decision.');

INSERT OVERWRITE lr_serverless_aws_us_catalog.meridian_reference.treaty_type VALUES
  ('QUOTA_SHARE', 'Quota Share', 'Proportional treaty ceding a fixed share of every risk in scope.'),
  ('SURPLUS', 'Surplus', 'Proportional treaty ceding the portion of each risk above the cedant''s retained line.'),
  ('XOL_PER_RISK', 'Excess of Loss (Per Risk)', 'Non-proportional cover for individual risk losses above an attachment point.'),
  ('XOL_CATASTROPHE', 'Excess of Loss (Catastrophe)', 'Non-proportional cover for accumulated losses from a single catastrophe event.');

INSERT OVERWRITE lr_serverless_aws_us_catalog.meridian_reference.underwriting_decision_type VALUES
  ('ACCEPT', 'Accept', 'Risk accepted at the quoted terms.'),
  ('REFER', 'Refer', 'Referred to a human underwriter; outside automatic authority.'),
  ('DECLINE', 'Decline', 'Risk declined.');

INSERT OVERWRITE lr_serverless_aws_us_catalog.meridian_reference.valuation_measure VALUES
  ('BEL', 'Best Estimate Liability', 'Present value of expected future cash flows, Solvency II best estimate.'),
  ('RISK_MARGIN', 'Risk Margin', 'Solvency II risk margin over the best estimate.'),
  ('TECHNICAL_PROVISION', 'Technical Provision', 'Best estimate plus risk margin.'),
  ('CASE_RESERVE_TOTAL', 'Case Reserves (Total)', 'Sum of open case reserves at the valuation date.'),
  ('IBNR', 'IBNR', 'Incurred-but-not-reported reserve at the valuation date.'),
  ('SCR', 'Solvency Capital Requirement', 'Solvency II capital requirement.'),
  ('OWN_FUNDS', 'Own Funds', 'Eligible own funds at the valuation date.'),
  ('CSM', 'Contractual Service Margin', 'IFRS 17 contractual service margin.'),
  ('RISK_ADJUSTMENT', 'Risk Adjustment', 'IFRS 17 risk adjustment for non-financial risk.');

